-- Ficha de Rikarena.
--
-- La biografía de relleno tenía dos frases sin un solo hecho. formation_year: la fila y la
-- ficha de Kinito Méndez dan 1990; se corrige aquí a 1994 (Wikipedia, coincide con el álbum
-- debut); la ficha de Kinito Méndez queda sin corregir, para el barrido final. Henry
-- Trinidad, Shiro Méndez, Guarionex Castro y Wester Hernández no tienen ficha propia.

UPDATE artists SET formation_year = 1994 WHERE slug = 'rikarena';

INSERT INTO artist_awards (artist_id, award_id, category_id, year, work, won, source)
SELECT ar.id, cat.award_id, cat.id, 1995, 'Sacúdelo que tiene arena', true, 'Wikipedia; El Nuevo Diario (nota "Rikarena junto a Jackeline Estévez")'
  FROM artists ar, award_categories cat JOIN awards a ON a.id = cat.award_id
 WHERE ar.slug = 'rikarena' AND a.name = 'Premios Casandra' AND cat.name = 'Orquesta Revelación del Año'
   AND NOT EXISTS (SELECT 1 FROM artist_awards w WHERE w.artist_id = ar.id AND w.category_id = cat.id AND w.year = 1995);

